import { LitElement, css, html, type PropertyValues } from "lit";
import { customElement, property } from "lit/decorators.js";
import { JzTabItemElement } from "../jz-tab-item/jz-tab-item.js";

/**
 * Tab group from the jz-tab-group capture. Layout chrome only — compose
 * `jz-tab-item` children (labels, hrefs, values). `selectedTab` matches a
 * child `value`, or its index as a string (`"0"`, `"1"`, …).
 */
@customElement("jz-tab-group")
export class JzTabGroupElement extends LitElement {
  static override styles = css`
    :host {
      display: block;
      width: 100%;
    }

    .root {
      box-sizing: border-box;
      display: flex;
      flex-direction: column;
      align-items: stretch;
      width: 100%;
      margin: 0;
      border: none;
      background: var(--jz-semantic-color-background-surface-subtle);
      border-radius: var(--jz-primitive-radius-md);
      padding: var(--jz-semantic-space-padding-xs)
        var(--jz-semantic-space-padding-sm);
    }

    .tabs {
      box-sizing: border-box;
      display: flex;
      flex-direction: row;
      align-items: center;
      justify-content: space-between;
      width: 100%;
      margin: 0;
      padding: 0;
      gap: 0;
      border: none;
      background: transparent;
    }

    ::slotted(jz-tab-item) {
      flex: 0 0 auto;
    }
  `;

  /**
   * Selected tab key: a child `value`, or index string (`"0"`, `"1"`, …).
   * Figma capture used `"0"` | `"1"` | `"2"`; any string is allowed in product.
   */
  @property({ type: String, attribute: "selected-tab", reflect: true })
  selectedTab = "0";

  #onClick = (event: Event) => {
    const path = event.composedPath();
    const item = path.find(
      (node): node is JzTabItemElement => node instanceof JzTabItemElement,
    );
    if (!item || item.parentElement !== this) return;

    const items = this.#items();
    const index = items.indexOf(item);
    if (index < 0) return;

    const key = item.value || String(index);
    if (this.selectedTab === key) return;
    this.selectedTab = key;
    this.dispatchEvent(
      new CustomEvent("change", {
        detail: { selectedTab: key, index },
        bubbles: true,
        composed: true,
      }),
    );
  };

  override connectedCallback() {
    super.connectedCallback();
    if (!this.hasAttribute("role")) {
      this.setAttribute("role", "tablist");
    }
    this.addEventListener("click", this.#onClick);
  }

  override disconnectedCallback() {
    this.removeEventListener("click", this.#onClick);
    super.disconnectedCallback();
  }

  protected override updated(changed: PropertyValues) {
    if (changed.has("selectedTab")) {
      this.#syncSelection();
    }
  }

  #items(): JzTabItemElement[] {
    return [
      ...this.querySelectorAll<JzTabItemElement>(":scope > jz-tab-item"),
    ];
  }

  #syncSelection() {
    const items = this.#items();
    for (let i = 0; i < items.length; i++) {
      const item = items[i]!;
      const key = item.value || String(i);
      item.selected = key === this.selectedTab;
    }
  }

  #onSlotChange = () => {
    this.#syncSelection();
  };

  override render() {
    return html`
      <div class="root">
        <div class="tabs" role="presentation">
          <slot @slotchange=${this.#onSlotChange}></slot>
        </div>
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    "jz-tab-group": JzTabGroupElement;
  }
}
